import{_ as e,o as s,c as o,a3 as t}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.2 基本概念与单路控制结构（单入单出）","description":"","frontmatter":{"translationSource":{"title":"1.2 基本概念与单路控制结构（单入单出）","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}]]},"headers":[],"relativePath":"zh/1-2-what-are-the-benefits-of-blocking-based-production.md","filePath":"zh/page-vjw47WlrDGyaYlemKyfnH8.md"}'),r={name:"zh/1-2-what-are-the-benefits-of-blocking-based-production.md"};function n(p,a,l,d,c,i){return s(),o("div",null,[...a[0]||(a[0]=[t('<div class="logistics-content"><h1 id="_1-2-基本概念与单路控制结构-单入单出" tabindex="-1">1.2 基本概念与单路控制结构（单入单出） <a class="header-anchor" href="#_1-2-基本概念与单路控制结构-单入单出" aria-label="Permalink to &quot;1\\.2 基本概念与单路控制结构（单入单出）&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>vjw47WlrDGyaYlemKyfnH8</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>本页最后更新：26-11-18</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2eb313d7cdd4b18c.q90-c7d9e3a625f6430f.webp" alt="12 基本概念与单路控制结构（单入单出）"></p><p>从仓库拿出源矿，送进精炼炉，做成晶体外壳送回仓库，可能这是所有管理员在终末地搭建的第一个产线。本节只用如上的结构，就能把所有的基本概念都讲清楚。</p><p><span id="source-block-EfJy3o35JjlXoZFlviZEJf"></span></p><h2 id="单路控制结构" tabindex="-1">单路控制结构 <a class="header-anchor" href="#单路控制结构" aria-label="Permalink to &quot;单路控制结构&quot;">​</a></h2><p><span id="source-block-wcYSbTRck5ZGy8cFoWnn64"></span></p><h3 id="上游对下游的直接控制" tabindex="-1">上游对下游的直接控制 <a class="header-anchor" href="#上游对下游的直接控制" aria-label="Permalink to &quot;上游对下游的直接控制&quot;">​</a></h3><p>可能大家伙还没明白，这里的控制在哪呢？实际上，不同于时钟控制和阻塞控制，这里体现的是最简单的<span class="mark-red"><strong>直接控制</strong></span>（或者叫原料控制，进料控制，流通控制，输入控制，上游控制，whatever）有多简单呢？</p><p><span class="mark-red"><strong>直接控制：机器有多少原料，才会生产多少产物，在产物不阻塞时</strong></span></p><p>简而言之，牛马不吃饭就不产出——当然需要在下游承接空间足够大，产物不会堵塞的情况下。在这里，上游给进了每分钟30的源矿，下游才有每分钟30的晶体外壳产出，这就形成了一种<span class="mark-purple"><strong>上游对下游的直接控制</strong></span>。</p><p>为什么呢？我们稍稍改变一下上游的输入，这里加一个每分钟18的限速，表示上游源矿输入速度降低到了每分钟18，显然，晶体外壳的输出速度也就降低到了每分钟18。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-482d8bded38eb0fa.q90-3ab541c93fda2869.webp" alt="12 基本概念与单路控制结构（单入单出）"></p><blockquote><p>随着认识的深入，我们逐渐会理解到<strong>控制</strong>实质上是一种<strong>因果关系</strong>。但这是后话了</p></blockquote><p>可能有人要说，如果仓库空了满了怎么办？在这一章，我们先不考虑仓库的问题，<u>假设理想情况，所有输出的原料仓库内总是充足的，所有输入的产物仓库也总是有空间承接</u>。我们将在以后讨论空仓和满仓的时候回来分析仓库的问题。</p><p><span id="source-block-weUEpoCNAQ3AYHIQAJ0XnE"></span></p><h3 id="下游对上游的阻塞控制" tabindex="-1">下游对上游的阻塞控制 <a class="header-anchor" href="#下游对上游的阻塞控制" aria-label="Permalink to &quot;下游对上游的阻塞控制&quot;">​</a></h3><p>我们调整一下限速器的位置，放到产出的一端，限制晶体外壳速度为每分钟18，会发生什么呢？</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-baea4a72ef4c4d5a.q90-bda2cb2546185cc4.webp" alt="12 基本概念与单路控制结构（单入单出）"></p><p>显然，大家伙都知道晶体外壳最开始的产速是每分钟30，不可能全部通过限速器，多余的就堵在传送带和机器里了，这样，<strong>阻塞</strong>就发生了。经过一段时间后，上游的源矿不可能无限输入，因此<strong>也堵上了</strong>，其速度当然也是每分钟18。</p><p>别看这里的速度跟前面的例子一模一样，它们的性质完全不同。这里形成的实质上是一种<span class="mark-purple"><strong>下游对上游的阻塞控制</strong></span>（或者叫间接控制，输出控制，下游控制，whatever）。为什么？我们仍然可以调整下游限速器的数值，可以想见，下游限速器调到多少，上游输入的速度就会跟着变到多少。</p><p><span class="mark-red"><strong>阻塞控制：机器产物能离开多少，才会消耗多少原料，在产物阻塞时</strong></span></p><blockquote><p>通过这两个例子我们可以发现，同样的生产速度可能对应着两种完全不同的状态。所以在对着报表debug时，光看一个生产速度并不能确定到底是上游缺货还是下游堵塞，那怎么办呢？请动动脑筋结合<strong>仓储量</strong>判断——希望这是本教程带来的最有用的第一课。</p></blockquote><p>可以认识到，两种控制的形成需要<strong>阻塞或者非阻塞</strong>的产线条件，也可以说不同的产线状态下会形成截然相反的控制关系。为了达成我们想要的控制目的，就需要<u>保证产线处于正确的状态</u>。</p><p>那么，这两种状态到底是怎么定义或者判断的？</p><hr><p><span id="source-block-83bJ0l7a3qVR9sKqjd3nOd"></span></p><h2 id="阻塞与流通" tabindex="-1">阻塞与流通 <a class="header-anchor" href="#阻塞与流通" aria-label="Permalink to &quot;阻塞与流通&quot;">​</a></h2><p>显然，我们没法从流量的角度去定义这两种状态，因为它们可以有完全相同的流量。</p><blockquote><p>但是，如果一定要从流量的角度出发，也可以考虑如下<strong>流量变化判据</strong>：假设把一个位置替换成容量无穷大的仓库（不管下游），如果这个位置的流量变大，说明是阻塞状态；如果流量不变，则是非阻塞状态。</p></blockquote><p>回顾我们上面阻塞例子，货物在传送带上并不是完全不动，而是蠕动一下停一下。从这个微观角度上，阻塞和非阻塞存在区别，以此入手：</p><p><span class="mark-red"><strong>（传送带、水管）阻塞：单个货物没有按照传送带或水管的标准速度运动，说明发生阻塞</strong></span></p><p>这里，标准速度指的就是传送带上货物2秒走1格，水管内流体货物1秒走2格。进一步地，我们把<strong>单个货物在机器生产中的表现</strong>也纳入进来，</p><p><span class="mark-red"><strong>（机器）阻塞：单个货物没有按照机器的标准生产速度消耗掉，说明发生阻塞</strong></span></p><p>回看阻塞的例子，对于每个源矿而言，需要等到精炼炉的源矿缓存有空位后，才能移动1格；源矿缓存要有空位，得等产物晶体外壳缓存有空位，才能进行生产消耗掉一个源矿；而晶体外壳缓存要有空位，得等限速器放产物过去才行。显然，对于传送带上的货物，都没有按照传送带的速度运动，机器中的每个源矿也没有按照生产外壳的标准速度（2秒1个）被消耗掉。</p><p>而对于非阻塞的例子，每个源矿/晶体外壳都按照正常的速度运动，一到精炼炉就在2秒后做成晶体外壳，即使在上游有限速，也是如此。可见这里提出的阻塞定义确实可行。</p><blockquote><p>绝大部分时候，还可以使用<strong>俺寻思判据</strong>：你觉得是阻塞就是阻塞，你觉得是流通就是流通，基本错不了。而且，一定要从上面的定义出发去判断再去推理会发生什么，还有点兜圈子费脑筋，还不如直接按照一般的认识来理解方便。</p></blockquote><p>非阻塞一般包括<span class="mark-red"><strong>流通</strong></span>和<strong>阻塞且流通</strong>两种情形，其中后者一般指传送带上每分钟30，或者在每分钟18限速的情况下输入输出也是每分钟18的<strong>临界情形（不等式取等号）</strong>。此时，机器中的输入输出缓存数量保持不变，可以是空也可以是满。不过在本教程中，这种情形比较少见，也可以直接当成<span class="mark-red"><strong>流通</strong></span>处理。那么我们可以相对应地定义流通：</p><p><span class="mark-red"><strong>流通：单个货物按照传送带或水管的标准速度运动，或按照机器的标准生产速度消耗掉</strong></span></p><blockquote><p>从控制的角度，阻塞且流通的情形处于直接控制和阻塞控制相互转化的过渡态。在上游的控制稍微严格一些（限速器值变小），就会成为上游的直接控制；同理下游的控制稍微严格一些，下游就会拿到控制权。</p></blockquote><hr><p><span id="source-block-LyHZQ9QaxNh6Yk5TVahMez"></span></p><h2 id="上游与下游" tabindex="-1">上游与下游 <a class="header-anchor" href="#上游与下游" aria-label="Permalink to &quot;上游与下游&quot;">​</a></h2><p>前面已经提到了<u>上游直接控制下游</u>和<u>下游阻塞控制上游</u>的概念。简单来说，对于一个机器或者一个元件，一段传送带来说，谁把货物送过来，谁就是它的<span class="mark-red"><strong>上游</strong></span>。它把货物送给谁，谁就是它的<span class="mark-red"><strong>下游</strong></span>。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0934982d55d8072f.q90-a9e92b4e2b3afc12.webp" alt="12 基本概念与单路控制结构（单入单出）"></p><blockquote><p>仍然可以使用<strong>俺寻思判据</strong>：你觉得是上游就是上游，你觉得是下游就是下游，这不会有人分不清吧（）。</p></blockquote><p>但是，如果我们在两个机器之间连了一条传送带，一直没有货物经过，或者说设计了某种赤石科技，要过100年才会送一个货物过来，这样也算上下游吗？从连接关系上看，当然也算；但对于我们所关心的问题而言，如果<u>有没有这个连接关系不影响结果，也就是说机器之间互相不发生联系</u>，那一般就不再认为机器之间具有上下游关系。</p><p>如果两个机器都是同一个机器/物流元件的上游或者都是下游，并且它们互相之间没有很明确的上下游关系的话，一般叫它们是<span class="mark-red"><strong>同级</strong></span>（同层级，同层次）。<strong>同级之间的控制</strong>是阻塞控制研究的重要内容~~，否则只从下往上或者从上往下压根就没什么可说的~~。我们在后面的小节中就会认识到这一点。</p><hr><p>一个机器/物流元件可以有很多个上游/下游，比如同级的上游，或者上游的上游之类。当我们说“上游直接控制下游”或者“下游直接控制上游”的时候，到底是指的是哪个上下游？事实上，<strong>控制具有一个传导的过程</strong>。在控制发生作用的初期，所控制到的就是<u>最相邻的上游或下游</u>。<span class="mark-blue">在前面的例子中，输入的源矿数量减少会使得机器工作减慢，从而产出的晶体外壳也减少；或是晶体外壳堵塞，使得源矿在机器中堵塞，又使得输入的源矿减少。</span>可见，这种控制会沿着上游或下游的方向逐渐传导，如果没有其他干扰，就会一直传导到源头或者产线最末尾为止，<strong>形成对整个上游或下游的控制</strong>。所以我们一般直接说控制上游控制下游也就可以了。不过呢，如果还有其他<u>同级的上游或同级的下游</u>，控制会至少传导到其中一个之上，我们也是很快就会认识到这一点。</p><p><a href="/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking">1.1 那我问你，什么是阻塞控制</a></p><p><a href="/endfield-skydoc/zh/1-4-prerequisite-basics">1.3 分流器控制结构（单入双出）</a></p><p><a href="/endfield-skydoc/zh/production-control-and-frontier-research">生产控制与前沿研究</a></p></div>',1)])])}const b=e(r,[["render",n]]);export{h as __pageData,b as default};
